fn arctan_approximation(x: i32) -> i32 {
    // A simple linear approximation with clamping to [-2, 2].
    // Division by 5 gives a coarse slope; values beyond ±10 get saturated.
    let y = x / 5;
    y.clamp(-2, 2)
}

fn arctan(xs: Vec<i32>) -> Vec<i32> {
    xs.into_iter()
      .map(arctan_approximation)
      .collect()
}

